// of a sum, which is what Fixpt's rep of it is (C347).
pub fn rp_datatype(x: &'static Rx, d: Str, args: Tys) -> List<&'static Dt> {
    let vs = rx_cv(x);
    if null_p(vs) {
        nil::<&'static Dt>()
    } else {
        let f = rp_dt_named(rp_dts(car(vs)), d);
        if (not(null_p(f)) && {
            let tagcase_ = car(f);
            match *tagcase_ {
                Dt::Dt(m, ps, vts) => {
                    (not(null_p(vts)) && i64_eq(size(ps), size(args)))
                }
            }
        }) {
            f
        } else {
            nil::<&'static Dt>()
        }
    }
}

