                                                return rx_fill(x, slot, str_lit("prompt-tag"), false, the::<Strings>(nil::<Str>()), the::<RpOperands>(kayak_rt::heap_cons(a2, kayak_rt::heap_cons(h2, kayak_rt::heap_cons(e2, kayak_rt::heap_cons(r2, kayak_rt::nil()))))));
