#[inline]
pub fn rp_hex_digits() -> Str {
    str_lit("0123456789abcdef")
}

/// Bytes `b` from `i` on, two hexadecimal digits each.
pub fn rp_hex_of(b: Bytes, i: Int) -> Str {
    if _gt_eq(i, bytevector_length(b)) {
        str_lit("")
    } else {
        let k = u8_to_int(bytevector_u8_ref(b, i));
        string_append(substring(rp_hex_digits(), quotient(k, int_lit(16)), _plus(quotient(k, int_lit(16)), int_lit(1))), string_append(substring(rp_hex_digits(), remainder(k, int_lit(16)), _plus(remainder(k, int_lit(16)), int_lit(1))), rp_hex_of(b, _plus(i, int_lit(1)))))
    }
}

// Importing: a rep's nodes, as `rep-nodes` gives them, back to a type of the
// checker's (C301). Each node by its slot; a bound variable by its binder's
// name at its place; a hole by its name; a node met again while it is being
// made, a recursive type's variable, `%mN`, its node then a `%mu`.
pub type RpIn = Product_11_12<RpNodes, List<Symbol>>;

pub fn rp_node_at(mut ns: RpNodes, mut k: Int) -> RpNodes {
    loop {
        if null_p(ns) {
            return nil::<Product_11_12_13_14_15<Int, Symbol, bool, List<Symbol>, List<&'static Sum_4node_5bound_4hole_5const_3sym_3int_4flag<Int, Product_11_12<Int, Int>, Int, Product_11_12_13<Str, Int, Str>, Symbol, Int, bool>>>>();
        } else if _eq(car(ns).0, k) {
            return kayak_rt::heap_cons(car(ns), kayak_rt::nil());
        } else {
            ns = cdr(ns);
            continue;
        }
    }
}

pub fn nth_symbol(mut xs: List<Symbol>, mut k: Int) -> Str {
    loop {
        if null_p(xs) {
            return str_lit("?");
        } else if _eq(k, int_lit(0)) {
            return symbol_to_string(car(xs));
        } else {
            (xs, k) = (cdr(xs), _minus(k, int_lit(1)));
            continue;
        }
    }
}

pub fn drop_sexps(mut xs: Sexps, mut n: i64) -> Sexps {
    loop {
        if (null_p(xs) || i64_lt_eq(n, 0i64)) {
            return xs;
        } else {
            (xs, n) = (cdr(xs), i64_minus(n, 1i64));
            continue;
        }
    }
}

pub fn drop_n(mut xs: RpOperands, mut n: i64) -> RpOperands {
    loop {
        if (null_p(xs) || i64_lt_eq(n, 0i64)) {
            return xs;
        } else {
            (xs, n) = (cdr(xs), i64_minus(n, 1i64));
            continue;
        }
    }
}

// A specification's text back, as the checker writes it (C303), from its
// nodes: `(spec (p …) r requires ensures)`.
pub fn rp_op_text(mut ns: RpNodes, mut a: RpOperand) -> Str {
    loop {
        let tagcase_ = a;
        match *tagcase_ {
            Sum_4node_5bound_4hole_5const_3sym_3int_4flag::Int(k) => {
                return int_to_string(k);
            }
            Sum_4node_5bound_4hole_5const_3sym_3int_4flag::Sym(n) => {
                return symbol_to_string(n);
            }
            Sum_4node_5bound_4hole_5const_3sym_3int_4flag::Node(j) => {
                let n = rp_node_at(ns, j);
                if null_p(n) {
                    return str_lit("?");
                } else {
                    let h = symbol_to_string(car(n).1);
                    let args = car(n).4;
                    let words = lambda1s(move |name: Str| {
                        string_append(str_lit("("), string_append(name, string_append(rp_ops_text(ns, args), str_lit(")"))))
                    });
                    if string_eq_p(h, str_lit("atom")) {
                        a = car(args);
                        continue;
                    } else if string_eq_p(h, str_lit("param")) {
                        return words(str_lit("p"));
                    } else if string_eq_p(h, str_lit("result")) {
                        return str_lit("(res)");
                    } else if string_eq_p(h, str_lit("length")) {
                        return words(str_lit("len"));
                    } else if string_eq_p(h, str_lit("nat")) {
                        return words(str_lit("natp"));
                    } else if string_eq_p(h, str_lit("rel")) {
                        return string_append(str_lit("(rel "), string_append(i64_to_string(rp_index_of(rp_rels(), {
                            let tagcase_ = car(args);
                            match *tagcase_ {
                                Sum_4node_5bound_4hole_5const_3sym_3int_4flag::Sym(n) => {
                                    symbol_to_string(n)
                                }
                                _ => {
                                    let other = tagcase_;
                                    str_lit("")
                                }
                            }
                        }, 0i64)), string_append(rp_ops_text(ns, cdr(args)), str_lit(")"))));
                    } else if string_eq_p(h, str_lit("shape")) {
                        return string_append(str_lit("(shape "), string_append(rp_op_text(ns, car(args)), string_append(str_lit(" "), string_append(rp_nth_string(rp_shapes(), {
                            let tagcase_ = car(cdr(args));
                            match *tagcase_ {
                                Sum_4node_5bound_4hole_5const_3sym_3int_4flag::Int(k) => {
                                    int_to_i64(k)
                                }
                                _ => {
                                    let other = tagcase_;
                                    -1i64
                                }
                            }
                        }), str_lit(")")))));
                    } else {
                        return words(h);
                    }
                }
            }
            _ => {
                let other = tagcase_;
                return str_lit("?");
            }
        }
    }
}

#[inline]
pub fn rp_ops_text(ns: RpNodes, r#as: RpOperands) -> Str {
    if null_p(r#as) {
        str_lit("")
    } else {
        string_append(str_lit(" "), string_append(rp_op_text(ns, car(r#as)), rp_ops_text(ns, cdr(r#as))))
    }
}

pub fn rp_spec_text(ns: RpNodes, j: Int) -> Str {
    let n = car(rp_node_at(ns, j));
    let bs = map(lambda1s(move |b: Symbol| {
        if string_eq_p(symbol_to_string(b), str_lit("")) {
            str_lit("%none")
        } else {
            symbol_to_string(b)
        }
    }), n.3);
    let args = n.4;
    string_append(str_lit("(spec ("), string_append(words_of(reverse(cdr(reverse(bs)))), string_append(str_lit(") "), string_append(last(bs), string_append(rp_ops_text(ns, args), str_lit(")"))))))
}

// What an import is in: the rep's nodes; its holes' names; the binders in
// scope, each its node's slot and its names; the nodes being made.
pub enum Ri {
    Ri(RpNodes, List<Symbol>, List<Product_11_12<Int, List<Symbol>>>, List<Int>),
}

pub fn ri(f0: RpNodes, f1: List<Symbol>, f2: List<Product_11_12<Int, List<Symbol>>>, f3: List<Int>) -> &'static Ri {
    kayak_rt::heap_alloc(Ri::Ri(f0, f1, f2, f3))
}

pub fn ri_binder_names(mut bs: List<Product_11_12<Int, List<Symbol>>>, mut slot: Int) -> List<Symbol> {
    loop {
        if null_p(bs) {
            return nil::<Symbol>();
        } else if _eq(car(bs).0, slot) {
            return car(bs).1;
        } else {
            bs = cdr(bs);
            continue;
        }
    }
}

/// Whether union node `k` is `datum`'s (`rx-datum`).
pub fn ri_datum_p(ns: RpNodes, k: Int, args: RpOperands) -> bool {
    (i64_eq(size(args), 10i64) && {
        let tagcase_ = car(drop_n(args, 7i64));
        match *tagcase_ {
            Sum_4node_5bound_4hole_5const_3sym_3int_4flag::Node(j) => {
                let n = rp_node_at(ns, j);
                (not(null_p(n)) && string_eq_p(symbol_to_string(car(n).1), str_lit("pairof")) && {
                    let tagcase_ = car(car(n).4);
                    match *tagcase_ {
                        Sum_4node_5bound_4hole_5const_3sym_3int_4flag::Node(m) => {
                            _eq(m, k)
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                })
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    })
}

